3459:pub open spec fn handle_get_then_delete_request_msg(msg: Message, s: APIServerState) -> (APIServerState, Message)
3460:    recommends
3461:        msg.content.is_get_then_delete_request(),
3462:{
3463:    let req = msg.content.get_get_then_delete_request();
3464:    // Step 1: get the object
3465:    let get_req = GetRequest {
3466:        key: req.key
3467:    };
3468:    let get_resp = handle_get_request(get_req, s);
3469:    match get_resp.res {
3470:        Ok(_) => {
3471:            let current_obj = s.resources[req.key()];
3472:            // Step 2: if the object exists, perform a check using a predicate on object
3473:            // The predicate: Is the current object owned by req.owner_ref?
3474:            // TODO: the predicate should be provided by clients instead of the hardcoded one
3475:            if current_obj.metadata.owner_references_contains(req.owner_ref) {
3476:                // Step 3: if the check passes, delete the object
3477:                let delete_req = DeleteRequest {
3478:                    key: req.key,
3479:                    preconditions: None,
3480:                };
3481:                let (s_prime, delete_resp) = handle_delete_request(delete_req, s);
3482:                (s_prime, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: delete_resp.res}))
3483:            } else {
3484:                (s, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: Err(APIError::TransactionAbort)}))
3485:            }
3486:        }
3487:        Err(err) => (s, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: Err(err)}))
3488:    }
3489:}
