3583:pub open spec fn run_garbage_collector() -> BuiltinControllersAction {
3584:    Action {
3585:        precondition: |input: BuiltinControllersActionInput, s: ()| {
3586:            let resources = input.resources;
3587:            let key = input.key;
3588:            let owner_references = resources[key].metadata.owner_references->0;
3589:            // The garbage collector is chosen by the top level state machine
3590:            &&& input.choice.is_GarbageCollector()
3591:            // The object exists in the cluster state
3592:            &&& resources.contains_key(input.key)
3593:            // and it has at least one owner reference
3594:            &&& resources[key].metadata.owner_references is Some
3595:            &&& resources[key].metadata.owner_references->0.len() > 0
3596:            // The garbage collector decides whether to delete an object by checking its owner references,
3597:            // it deletes the object if for each owner reference...
3598:            &&& forall |i| #![trigger owner_references[i]] 0 <= i < owner_references.len() ==> {
3599:                // the referred owner object does not exist in the cluster state
3600:                ||| !resources.contains_key(owner_reference_to_object_reference(owner_references[i], key.namespace))
3601:                // or it exists but has a different uid
3602:                // (which means the actual owner was deleted and another object with the same name gets created again)
3603:                ||| resources[owner_reference_to_object_reference(owner_references[i], key.namespace)].metadata.uid != Some(owner_references[i].uid)
3604:            }
3605:        },
3606:        transition: |input: BuiltinControllersActionInput, s: ()| {
3607:            // GC set the preconditions to the object's uid in its delete request
3608:            // See https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/controller/garbagecollector/operations.go#L52-L61
3609:            let preconditions = PreconditionsView {
3610:                uid: input.resources[input.key].metadata.uid,
3611:                resource_version: None,
3612:            };
3613:            let delete_req_msg = built_in_controller_req_msg(
3614:                input.rpc_id_allocator.allocate().1, delete_req_msg_content(input.key, Some(preconditions))
3615:            );
3616:            let output = BuiltinControllersActionOutput {
3617:                send: Multiset::singleton(delete_req_msg),
3618:                rpc_id_allocator: input.rpc_id_allocator.allocate().0,
3619:            };
3620:            ((), output)
3621:        },
3622:    }
3623:}
