3385:            // so the resource version counter does not increase here,
3386:            // and the resource version of this object remains the same.
3387:            (s, UpdateStatusResponse{res: Ok(old_obj)})
3388:        } else {
3389:            // UpdateStatus changes something in the object (in status), so we set it a newer resource version,
3390:            // which is the current rv counter.
3391:            let updated_obj_with_new_rv = updated_obj.with_resource_version(s.resource_version_counter);
3392:            if updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types) is Some {
3393:                // UpdateStatus fails.
3394:                (s, UpdateStatusResponse{res: Err(updated_object_validity_check(updated_obj_with_new_rv, old_obj, installed_types)->0)})
3395:            } else {
3396:                // UpdateStatus succeeds.
3397:                (APIServerState {
3398:                    resources: s.resources.insert(req.key(), updated_obj_with_new_rv),
3399:                    resource_version_counter: s.resource_version_counter + 1, // Advance the rv counter
3400:                    ..s
3401:                }, UpdateStatusResponse{res: Ok(updated_obj_with_new_rv)})
3402:            }
3403:        }
3404:    }
