3660:            let initialized_ongoing_reconcile = OngoingReconcile {
3661:                triggering_cr: s.scheduled_reconciles[cr_key],
3662:                pending_req_msg: None,
3663:                local_state: (model.init)(),
3664:                reconcile_id: reconcile_id
3665:            };
3666:            let s_prime = ControllerState {
3667:                ongoing_reconciles: s.ongoing_reconciles.insert(cr_key, initialized_ongoing_reconcile),
3668:                scheduled_reconciles: s.scheduled_reconciles.remove(cr_key),
3669:                reconcile_id_allocator: new_allocator,
3670:                ..s
3671:            };
3672:            let output = ControllerActionOutput {
3673:                send: Multiset::empty(),
3674:                rpc_id_allocator: input.rpc_id_allocator,
3675:            };
