3681:pub open spec fn continue_reconcile(model: ReconcileModel, controller_id: int) -> ControllerAction {
3682:    Action {
3683:        precondition: |input: ControllerActionInput, s: ControllerState| {
3684:            if input.scheduled_cr_key is Some {
3685:                let cr_key = input.scheduled_cr_key->0;
3686:
3687:                &&& cr_key.kind == model.kind
3688:                &&& s.ongoing_reconciles.contains_key(cr_key)
3689:                &&& !(model.done)(s.ongoing_reconciles[cr_key].local_state)
3690:                &&& !(model.error)(s.ongoing_reconciles[cr_key].local_state)
3691:                &&& if s.ongoing_reconciles[cr_key].pending_req_msg is Some {
3692:                    &&& input.recv is Some
3693:                    &&& (input.recv->0.content.is_APIResponse() || input.recv->0.content.is_ExternalResponse())
3694:                    &&& resp_msg_matches_req_msg(input.recv->0, s.ongoing_reconciles[cr_key].pending_req_msg->0)
3695:                } else {
3696:                    input.recv is None
3697:                }
3698:            } else {
3699:                false
3700:            }
3701:        },
3702:        transition: |input: ControllerActionInput, s: ControllerState| {
3703:            let cr_key = input.scheduled_cr_key->0;
3704:            let reconcile_state = s.ongoing_reconciles[cr_key];
3705:            let resp_o = if input.recv is Some {
3706:                if input.recv->0.content.is_APIResponse() {
3707:                    Some(ResponseContent::KubernetesResponse(input.recv->0.content.get_APIResponse_0()))
3708:                } else {
3709:                    Some(ResponseContent::ExternalResponse(input.recv->0.content.get_ExternalResponse_0()))
3710:                }
3711:            } else {
3712:                None
3713:            };
3714:            let (local_state_prime, req_o) = (model.transition)(reconcile_state.triggering_cr, resp_o, reconcile_state.local_state);
3715:            let (pending_req_msg, send, rpc_id_allocator_prime) = if req_o is Some {
3716:                let pending_req_msg = match req_o->0 {
3717:                    RequestContent::KubernetesRequest(req) => {
3718:                        Some(controller_req_msg(controller_id, cr_key, input.rpc_id_allocator.allocate().1, req))
3719:                    },
3720:                    RequestContent::ExternalRequest(req) => {
3721:                        Some(controller_external_req_msg(controller_id, cr_key, input.rpc_id_allocator.allocate().1, req))
3722:                    }
3723:                };
3724:                (pending_req_msg, Multiset::singleton(pending_req_msg->0), input.rpc_id_allocator.allocate().0)
